for (i = -5; i <= 5; ++i) {
  if (i != 0) {
    draw((i,-0.2)--(i,0.2));
    draw((-0.2,i)--(0.2,i));
   label("$" + string(i) + "$", (i,-0.2), S);
   label("$" + string(i) + "$", (-0.2,i), W);
  }
}

